import networkx as nx
import matplotlib.pyplot as plt


from collections import deque



def maze_to_tree_graph1(maze):
    if not maze:
        return

    rows = len(maze)
    cols = len(maze[0]) if rows else 0

    walkable_cells = []
    for y in range(1, rows - 1, 2):
        for x in range(1, cols - 1, 2):
            value = maze[y][x]
            if value in (0, 2):
                walkable_cells.append((x, y))

    if not walkable_cells:
        return

    start = (1,1)


    graph = nx.Graph()
    for x, y in walkable_cells:
        graph.add_node((x, y))

    for x, y in walkable_cells:
        node = (x, y)
        if x + 2 < cols and maze[y][x + 1] == 0 and (x + 2, y) in graph:
            graph.add_edge(node, (x + 2, y))
        if y + 2 < rows and maze[y + 1][x] == 0 and (x, y + 2) in graph:
            graph.add_edge(node, (x, y + 2))

    if not nx.is_tree(graph):
        return

    root = start
    parent_map = {root: None}
    children_map = {root: []}
    stack = [root]

    while stack:
        node = stack.pop()
        for neighbor in graph.neighbors(node):
            if neighbor == parent_map[node]:
                continue
            if neighbor in parent_map:
                continue
            parent_map[neighbor] = node
            children_map.setdefault(neighbor, [])
            children_map[node].append(neighbor)
            stack.append(neighbor)

    subtree_sizes = {}

    def compute_subtree_size(node):
        size = 1
        for child in children_map.get(node, []):
            size += compute_subtree_size(child)
        subtree_sizes[node] = size
        return size

    compute_subtree_size(root)

    positions = {}
    level_gap = 1.8
    sibling_gap = 1.2
    

    def place_subtree(node, depth, parent_x):
        children = children_map.get(node, [])
        if not children:
            positions[node] = (parent_x, -depth * level_gap)
            return

        total_weight = sum(subtree_sizes[child] for child in children)
        start_x = parent_x - (total_weight * sibling_gap) / 2.0
        cursor_x = start_x

        for child in children:
            child_weight = subtree_sizes[child]
            child_x = cursor_x + (child_weight * sibling_gap) / 2.0
            positions[child] = (child_x, -(depth + 1) * level_gap)
            place_subtree(child, depth + 1, child_x)
            cursor_x += child_weight * sibling_gap


        

    positions[root] = (0.0, 0.0)
    place_subtree(root, 0, 0.0)

    labels = {}

    end = (cols - 2, rows - 2)
    for node in graph.nodes:
        if node == root:
            labels[node] = "Start"
        elif node == end:
            labels[node] = "End"
        else:
            labels[node] = f"({node[0]}, {node[1]})"
            #pass
    
    fig, ax = plt.subplots(figsize=(10, 10))
    nx.draw_networkx(
        graph,
        pos=positions,
        labels=labels,
        with_labels=True,
        node_size=10,
        #node_color="#dbeafe",
        node_color="#dbeafe",
        edge_color="#374151",
        linewidths=1.2,
        font_size=9,
        font_weight="bold",
        arrows=False,
    )

    ax.set_aspect("equal")
    ax.axis("off")
    plt.tight_layout()
    plt.show(block=False)
    plt.pause(0.001)

